```tsx
import { useId } from "react";
import type { ReactElement } from "react";
import "./EmptyState.css";

export interface EmptyStateProps {
  title: string;
  message: string;
  actionLabel: string;
  onAction: () => void;
}

export function EmptyState({
  title,
  message,
  actionLabel,
  onAction,
}: EmptyStateProps): ReactElement {
  const titleId = useId();

  return (
    <section className="empty-state" aria-labelledby={titleId}>
      <h2 id={titleId} className="empty-state__title">
        {title}
      </h2>
      <p className="empty-state__message">{message}</p>
      <button type="button" className="empty-state__action" onClick={onAction}>
        {actionLabel}
      </button>
    </section>
  );
}
```

```css
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: clamp(0.75rem, 1.5vh, 1rem);
  max-width: 32rem;
  margin: 0 auto;
  padding: clamp(2rem, 6vh, 4rem) 1.5rem;
  text-align: center;
  color: var(--ink);
  background: var(--slide);
  font: inherit;
}

.empty-state__title {
  margin: 0;
  font-size: clamp(1.25rem, 2.5vw + 0.5rem, 1.75rem);
  font-weight: 600;
  line-height: 1.25;
  color: var(--ink);
}

.empty-state__message {
  margin: 0;
  font-size: clamp(0.95rem, 0.6vw + 0.8rem, 1.05rem);
  line-height: 1.5;
  color: var(--muted);
}

.empty-state__action {
  margin-top: clamp(0.5rem, 1vh, 0.75rem);
  padding: 0.6rem 1.25rem;
  font: inherit;
  font-weight: 600;
  line-height: 1.2;
  color: var(--slide);
  background: var(--myelin);
  border: 1px solid var(--myelin);
  border-radius: 999px;
  cursor: pointer;
  transition: box-shadow 150ms ease;
}

.empty-state__action:hover {
  box-shadow: 0 0 0 3px var(--myelin-wash);
}

:root[data-motion="reduce"] .empty-state__action {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .empty-state__action {
    transition: none;
  }
}
